  const ts = atMs ?? Date.now();
  const key = dateKey(ts);
  const raw = await AsyncStorage.getItem(ACTIVITY_LOG_KEY);
  const map: ActivityMap = raw ? JSON.parse(raw) : {};
  map[key] = (map[key] ?? 0) + 1;
  await AsyncStorage.setItem(ACTIVITY_LOG_KEY, JSON.stringify(map));
}

